// Turns the configured lookback window into a concrete ISO timestamp
// we can hand straight to PostgREST as a `gte.` filter on both tables.

const config = $('⚙️ Configuration').first().json;
const sinceTimestamp = new Date(Date.now() - config.windowHours * 60 * 60 * 1000).toISOString();

return [{
  json: {
    ...config,
    sinceTimestamp
  }
}];

// Normalises this HTTP Request node's output into a single item,
// regardless of whether n8n auto-split the JSON array response into
// multiple items or returned it as one item containing the whole array.

const raw = $input.all();
let records;

if (raw.length === 1 && Array.isArray(raw[0].json)) {
  records = raw[0].json;
} else {
  records = raw.map(i => i.json).filter(j => j && Object.keys(j).length > 0);
}

return [{
  json: {
    table: 'account_actions',
    records,
    count: records.length
  }
}];

// Normalises this HTTP Request node's output into a single item,
// regardless of whether n8n auto-split the JSON array response into
// multiple items or returned it as one item containing the whole array.

const raw = $input.all();
let records;

if (raw.length === 1 && Array.isArray(raw[0].json)) {
  records = raw[0].json;
} else {
  records = raw.map(i => i.json).filter(j => j && Object.keys(j).length > 0);
}

return [{
  json: {
    table: 'verification_audit',
    records,
    count: records.length
  }
}];

// Merges the two aggregated branches (account_actions + verification_audit)
// back into one item, and decides whether today's digest should be
// skipped (only relevant if you've turned onlySendIfActivity on).

const config = $('⚙️ Configuration').first().json;
const items = $input.all().map(i => i.json);

const accountActions    = items.find(i => i.table === 'account_actions')     || { records: [], count: 0 };
const verificationAudit = items.find(i => i.table === 'verification_audit') || { records: [], count: 0 };

const totalCount = accountActions.count + verificationAudit.count;
const shouldSkip = Boolean(config.onlySendIfActivity) && totalCount === 0;

return [{
  json: {
    ...config,
    accountActions: accountActions.records,
    verificationAudit: verificationAudit.records,
    totalCount,
    shouldSkip
  }
}];

// Builds the HTML body for the daily governance digest.
// Adjust the field names below to match your actual `account_actions`
// and `verification_audit` columns if they differ - see the README.

const {
  accountActions, verificationAudit, totalCount,
  windowHours, adminEmailsRaw, fromAddress
} = $json;

function fmt(ts) {
  return ts ? new Date(ts).toLocaleString() : '—';
}

function actionRows(rows) {
  if (!rows.length) {
    return `<tr><td colspan="5" style="padding:10px;color:#64748b;font-style:italic;">No account actions in this window.</td></tr>`;
  }
  return rows.map(r => {
    const action     = r.action_type || r.action || '(unknown)';
    const targetUser = r.target_label || r.target_user_email || r.target_user_name || r.target_user_id || '(unknown)';
    const performedBy= r.performed_by_name || r.performed_by_email || r.performed_by || r.admin_id || '(unknown)';
    const reason      = r.reason || r.notes || '—';
    return `
      <tr>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${fmt(r.created_at)}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;font-weight:600;">${action}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${targetUser}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${performedBy}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${reason}</td>
      </tr>`;
  }).join('');
}

function auditRows(rows) {
  if (!rows.length) {
    return `<tr><td colspan="5" style="padding:10px;color:#64748b;font-style:italic;">No verification decisions in this window.</td></tr>`;
  }
  return rows.map(r => {
    const trackId    = r.track_id || r.tracking_id || r.claim_id || r.id;
    const decision   = r.decision || r.status || '(unknown)';
    const reviewedBy = r.reviewed_by_name || r.reviewed_by_email || r.reviewed_by || r.admin_id || '(unknown)';
    const notes       = r.notes || r.reason || '—';
    const color = /reject|deny|decline/i.test(decision) ? '#b91c1c' : '#15803d';
    return `
      <tr>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${fmt(r.decided_at)}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${trackId}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;font-weight:600;color:${color};">${decision}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${reviewedBy}</td>
        <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${notes}</td>
      </tr>`;
  }).join('');
}

const html = `
  <div style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto;">
    <h2 style="color:#1e3a8a;">Daily Governance Digest</h2>
    <p style="color:#334155;">
      ${totalCount} total action(s) across the platform in the last ${windowHours} hours:
      ${accountActions.length} account action(s), ${verificationAudit.length} verification decision(s).
    </p>

    <h3 style="color:#1e3a8a;margin-top:24px;">Account Actions</h3>
    <table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead>
        <tr style="background:#f1f5f9;text-align:left;">
          <th style="padding:8px;">Time</th>
          <th style="padding:8px;">Action</th>
          <th style="padding:8px;">Target User</th>
          <th style="padding:8px;">Performed By</th>
          <th style="padding:8px;">Reason</th>
        </tr>
      </thead>
      <tbody>${actionRows(accountActions)}</tbody>
    </table>

    <h3 style="color:#1e3a8a;margin-top:24px;">Verification Decisions</h3>
    <table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead>
        <tr style="background:#f1f5f9;text-align:left;">
          <th style="padding:8px;">Time</th>
          <th style="padding:8px;">Track ID</th>
          <th style="padding:8px;">Decision</th>
          <th style="padding:8px;">Reviewed By</th>
          <th style="padding:8px;">Notes</th>
        </tr>
      </thead>
      <tbody>${auditRows(verificationAudit)}</tbody>
    </table>

    <p style="color:#64748b;font-size:12px;margin-top:20px;">
      Automated daily governance digest from the Richfield Connect moderation workflow.
      Full history remains available on the admin console's audit log page.
    </p>
  </div>`;

const recipients = (adminEmailsRaw || '')
  .split(',')
  .map(e => e.trim())
  .filter(Boolean);

const todayLabel = new Date().toLocaleDateString();

return [{
  json: {
    html,
    subject: `Governance Digest — ${todayLabel} (${totalCount} action${totalCount === 1 ? '' : 's'})`,
    recipients,
    fromAddress
  }
}];
